function validate([intervals, k]) {
  if (intervals.length < 1 || intervals.length > 100000) return 'intervals holds 1 to 100000 intervals.';
  for (const pair of intervals) {
    if (pair.length !== 2) return 'Each interval is a pair [start, end].';
    const [start, end] = pair;
    if (start < 1 || start > end || end > 1000000000) return 'Each interval needs 1 <= start <= end <= 10^9.';
  }
  if (k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  return null;
}

