function minConnectedGroups(intervals, k) {
  // Count groups by sweeping the intervals in order and tracking how far the covered stretch reaches.
  const countGroups = (list) => {
    const ordered = list.map(pair => pair.slice()).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    let count = 0;
    let reach = -Infinity;
    for (const [s, e] of ordered) {
      if (s > reach) count++;
      reach = Math.max(reach, e);
    }
    return count;
  };
  // A longer new interval never hurts, and an optimal one can be slid to begin at some interval's end,
  // so trying [x, x + k] for x at every endpoint (and every endpoint minus k) covers it.
  let best = Infinity;
  for (const [s, e] of intervals) {
    for (const x of [s - k, s, e - k, e]) {
      best = Math.min(best, countGroups([...intervals, [x, x + k]]));
    }
  }
  return best;
}

