function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const intervals = [];
    let cursor = 1 + Math.floor(rand() * 1000);
    for (let i = 0; i < n; i++) {
      const length = Math.floor(rand() * 50000);
      intervals.push([cursor, cursor + length]);
      // The next interval starts inside this one or after a gap of up to 100000.
      cursor += Math.floor(rand() * (length + 100000));
    }
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [intervals[i], intervals[j]] = [intervals[j], intervals[i]];
    }
    return [intervals, 1 + Math.floor(rand() * 300000)];
  }
  const n = 1 + Math.floor(rand() * 7);
  const intervals = Array.from({ length: n }, () => {
    const start = 1 + Math.floor(rand() * 25);
    return [start, start + Math.floor(rand() * 5)];
  });
  return [intervals, 1 + Math.floor(rand() * 6)];
}
